    }

    /**
     * Binds the person's claims to the figures of a statement: each claim in {@code figures} is stated at
     * its figure (null: n/a), and every other claim of theirs is left unbound.
     */
    public void bind(String sheetId, long personId, java.util.Map<Long, BigDecimal> figures) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ?",
                sheetId, personId);
        figures.forEach((id, figure) -> jdbc.update(
                "UPDATE claim SET stated = TRUE, stated_due = ? WHERE id = ?", figure, id));
    }

    /**
     * The sheet's next claim number. The counter row is locked by the increment until the transaction
     * commits, so two claims opened at once get different numbers.
     */
    private long nextNumber(String sheetId) {
        try {
            jdbc.update("INSERT INTO claim_number_seq (sheet_id, last_number) SELECT ?, 0 "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number_seq WHERE sheet_id = ?)", sheetId, sheetId);
        } catch (DuplicateKeyException e) {
            // Another user started the sheet's counter at the same moment.
        }
        jdbc.update("UPDATE claim_number_seq SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
        return jdbc.queryForObject("SELECT last_number FROM claim_number_seq WHERE sheet_id = ?", Long.class,
                sheetId);
    }

    /** The next number of the sheet's sequence for the period ("" for no period); locked like {@link #nextNumber(String)}. */
    private long nextNumber(String sheetId, String scope) {
        try {
            jdbc.update("INSERT INTO claim_period_number_seq (sheet_id, scope, last_number) SELECT ?, ?, 0 "
                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number_seq WHERE sheet_id = ? AND scope = ?)",
                    sheetId, scope, sheetId, scope);
        } catch (DuplicateKeyException e) {
            // Another user started the period's counter at the same moment.
        }
        jdbc.update("UPDATE claim_period_number_seq SET last_number = last_number + 1 WHERE sheet_id = ? AND scope = ?",
                sheetId, scope);
        return jdbc.queryForObject("SELECT last_number FROM claim_period_number_seq WHERE sheet_id = ? AND scope = ?",
                Long.class, sheetId, scope);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim made by a person on a sheet. {@code amount} is 0.00 or more, in two decimals. {@code number}
 * is given when the claim is opened (null for a draft or a voided claim). {@code settledDue} is the due fixed
 * when it was settled (null when not settled, or settled while no rate of its grade applied on its date).
 * {@code openedBy} is the user who opened it (null when never opened). {@code stated} is whether its person's
 * last statement bound it, at {@code statedDue} (null when it had no figure then). A claim with a negative amount is a
 * correction: {@code corrects} is the number of the SETTLED claim of the same person it corrects (null for any other claim).
 * {@code dueBy} is fixed when the claim is made, and kept when its terms or its date change later.
 * {@code deferredUntil} is the date an OPEN claim was deferred to (null when never deferred).
 * {@code proofs} is how many proofs it has been given (0 for none).
 */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs) {

    public Claim with(ClaimInput input, LocalDate date) {
        return new Claim(id, sheetId, personId, input.amount(), date, input.note(), status, number, settledDue, openedBy, stated, statedDue, input.corrects(), dueBy, deferredUntil, proofs);
    }

    public Claim withStatus(ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs);
    }

    /** The claim moved to another person: unbound from any statement, so live until their next one. */
    public Claim withPerson(long personId) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null, corrects, dueBy, deferredUntil, proofs);
    }

    /** The claim deferred to {@code until}. */
    public Claim withDeferredUntil(LocalDate until) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, until, proofs);
    }

    /** The claim with {@code proofs} proofs. */
    public Claim withProofs(int proofs) {
        return new Claim(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, dueBy, deferredUntil, proofs);
    }

    /**
     * Whether the claim is deferred on {@code today}: an OPEN claim deferred to a date the sheet's today has not reached
     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && (today == null || today.isBefore(deferredUntil));
    }

    /** A correction: its due is its amount times the rate, with no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-MM-dd, the status by name, the number (null when it has none), the due fixed on settling (null when it has none), who opened it (null when never opened), whether its person's last statement bound it, the figure it bound (null when it has none) the number a correction corrects (null for any other claim) and the date it is due by, as yyyy-MM-dd, its status log, oldest first (empty when not listed with it), and the date it was deferred to, as yyyy-MM-dd (null when never deferred), and how many proofs it has been given. */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue,
        String corrects, String dueBy, java.util.List<String> log, String deferredUntil, int proofs) {

    public static ClaimResponse from(Claim claim) {
        return from(claim, java.util.List.of());
    }

    public static ClaimResponse from(Claim claim, java.util.List<String> log) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.settledDue() == null ? null : claim.settledDue().toPlainString(), claim.openedBy(), claim.stated(),
                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
                claim.dueBy().toString(), log,
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class ApplyReassign {
    // Only a role the permission matrix allows to reassign (by default a steward) moves a claim, and only a DRAFT, OPEN or PENDING one, to another person on the sheet who was not
    // retired by its date. A correction stays with the person whose settled claim it corrects. Stored only if the
    // claim still has the person and status it was loaded with.
    public void apply(@RequestBody(required = false) ReassignRequest body, @Val Claim claim, Claims claims,
            People people, Settings settings, ServerHttpConnection connection, Out<ClaimResponse> responseOut,
            Out<Person> toOut) throws ClaimReassignRefusedException, ClaimAfterRetirementException {
        String user = Audit.user(connection).trim();
        if (!settings.permits(claim.sheetId(), "reassign", user)) {
            throw new ClaimReassignRefusedException("Your role is not allowed to move a claim to another person.");
        }
        if (!(claim.status() == ClaimStatus.DRAFT || claim.status().isOpen())) {
            throw new ClaimReassignRefusedException("A " + claim.status() + " claim cannot move to another person.");
        }
        if (claim.isCorrection()) {
            throw new ClaimReassignRefusedException("A correction stays with the person whose claim it corrects.");
        }
        Person to = body == null || body.personId() == null ? null : people.find(claim.sheetId(), body.personId());
        if (to == null) {
            throw new ClaimReassignRefusedException("Choose a person on this sheet to move the claim to.");
        }
        if (to.id() == claim.personId()) {
            throw new ClaimReassignRefusedException("The claim is already " + to.name() + "'s.");
        }
        RefuseRetiredInput.check(to, claim.date());
        Claim moved = claims.reassign(claim, to.id());
        if (moved == null) {
            throw new ClaimReassignRefusedException("The claim has changed since it was loaded.");
        }
        responseOut.set(ClaimResponse.from(moved));
        toOut.set(to);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.plugin.variable.Val;

public class RefuseClosedClaim {
    // A claim dated inside a closed period cannot be edited, opened, settled or voided.
    public void refuse(@Val Claim claim, Periods periods) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(claim.sheetId(), claim.date());
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: its claims cannot change.");
        }
    }
}

