package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AddClaim {
    // The due-by is fixed now: the claim's date plus the terms of its person's grade in force on that date.
    // Its status log starts with its DRAFT line, at its due as shown now.
    public void add(@Val ClaimInput input, @Val Person person, Claims claims, Sheets sheets, Settings settings,
            Rollup rollup, ServerHttpConnection connection, Out<Claim> claimOut) {
        LocalDate date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        LocalDate dueBy = date.plusDays(settings.terms(person.sheetId(), person.gradeOn(date), date));
        Claim claim = claims.add(person.sheetId(), person.id(), input.amount(), date, input.note(), input.corrects(),
                dueBy);
        claims.log(claim, Audit.user(connection).trim(), sheets.today(person.sheetId()), rollup.figure(claim));
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AuditRollup {
    // After the change's own lines: one ROLLUP per person whose figures moved (a new person counts as moved),
    // in the order they were added, then TOTALS when a sheet total moved.
    public void audit(@PathVariable("sheetId") String sheetId, @Val Figures before, Rollup rollup,
            ServerHttpConnection connection, Audit audit) {
        RollupLines.record(sheetId.trim(), Audit.user(connection), before, rollup, audit);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class SnapshotRollup {
    // The sheet's figures before the change, for AuditRollup to compare with after it.
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<Figures> before) {
        before.set(rollup.figures(sheetId.trim()));
    }
}
